// #cea3ed (6a993d7ae4562a7e48cea3ed) «ניהול הזמנות ומשתמשים קיימים בעסק» — строка вступившего участника на /settings/users:
// 4 пункта меню и тексты окон «חסימת משתמש» / «הסרה מהעסק» / «ביטול החסימה». Окна закрываются Esc БЕЗ подтверждения.
// Кейс UA-008 · spec: specs/user-access.md (раздел 4) · seed: tests/seed.business.spec.ts.
// Защита: после загрузки списка все записи к Supabase (POST/PUT/PATCH/DELETE к /rest/v1 и /functions/v1) обрываются и считаются —
// даже случайное подтверждение не заблокирует и не удалит реальный аккаунт (сохранённые слоты .qa/auth/* блокировать запрещено).
// Само подтверждение блокировки/удаления и вход участника — вручную, UA-009.
import * as path from 'path';
import { Locator, Page } from '@playwright/test';
import { test, expect } from '../../fixtures';

test.use({ storageState: path.resolve(__dirname, '../../../auth/business.json') });

const HASH = '#cea3ed #6a993d7ae4562a7e48cea3ed';
const MEMBER_MENU = /^פעולות עבור (?!ההזמנה של )/;

async function guardWrites(page: Page) {
  const blocked: string[] = [];
  await page.route(/\/(rest|functions)\/v1\//, async (route) => {
    const method = route.request().method();
    if (['GET', 'HEAD', 'OPTIONS'].includes(method)) return route.continue();
    blocked.push(`${method} ${route.request().url()}`);
    return route.abort();
  });
  return blocked;
}

async function memberName(row: Locator) {
  const label = (await row.getByRole('button', { name: MEMBER_MENU }).getAttribute('aria-label')) ?? '';
  return label.replace(/^פעולות עבור /, '').trim();
}

async function openMemberMenu(page: Page, name: string) {
  const menuName = `פעולות עבור ${name}`;
  await page.getByRole('button', { name: menuName, exact: true }).click();
  const menu = page.getByRole('menu', { name: menuName });
  await expect(menu).toBeVisible();
  return menu;
}

async function closeWithoutConfirm(page: Page, dialog: Locator) {
  await page.keyboard.press('Escape');
  if (await dialog.isVisible()) await dialog.getByRole('button', { name: /^(ביטול|סגירה|השארה)/ }).first().click();
  await expect(dialog).toBeHidden();
}

test.describe(`Пользователи и приглашения — меню и окна строки участника (${HASH})`, () => {
  test(`business: у активного «מנהל/ת מגייס/ת» меню «שינוי הרשאה / עריכת שיוך לסימולציות / חסימת משתמש / הסרה מהעסק», тексты окон блокировки и удаления; без подтверждения @desktop @prod-safe ${HASH}`, async ({ page }) => {
    await page.goto('/settings/users');
    await expect(page.getByRole('heading', { level: 1, name: 'משתמשים והרשאות' })).toBeVisible();
    const rows = page.getByTestId('user-row');
    await expect(rows.first()).toBeVisible();
    const blocked = await guardWrites(page);

    // Своя строка («אתה») — без меню действий.
    const self = rows.filter({ hasText: 'אתה' });
    await expect(self).toHaveCount(1);
    await expect(self.getByRole('button', { name: /^פעולות עבור/ })).toHaveCount(0);

    // Активный מנהל/ת מגייס/ת (не приглашение, не חסום).
    const active = rows
      .filter({ has: page.getByRole('button', { name: MEMBER_MENU }) })
      .filter({ hasText: 'מנהל/ת מגייס/ת' })
      .filter({ hasText: 'פעיל' })
      .filter({ hasNotText: 'חסום' })
      .filter({ hasNotText: 'ממתין להצטרפות' });
    await expect(active.first(), 'в testim нужен хотя бы один активный מנהל/ת מגייס/ת').toBeVisible();
    const row = active.first();
    const name = await memberName(row);
    expect(name, 'имя участника из aria-label кнопки меню').toBeTruthy();

    // Меню участника — 4 пункта, без действий приглашения (треб.1).
    let menu = await openMemberMenu(page, name);
    await expect(menu.getByRole('menuitem')).toHaveText(['שינוי הרשאה', 'עריכת שיוך לסימולציות', 'חסימת משתמש', 'הסרה מהעסק']);
    for (const item of ['העתקת קישור', 'שליחה חוזרת', 'ביטול ההזמנה']) await expect(menu.getByRole('menuitem', { name: item })).toHaveCount(0);

    // «חסימת משתמש» — окно (AC3: сессия заканчивается, вход невозможен, данные сохраняются).
    const dialog = page.getByRole('dialog').or(page.getByRole('alertdialog'));
    await menu.getByRole('menuitem', { name: 'חסימת משתמש' }).click();
    await expect(dialog).toContainText(`לחסום את ${name}?`);
    await expect(dialog).toContainText(`הסשן הפעיל של ${name} יסתיים מיד, ולא ניתן יהיה להתחבר עד לביטול החסימה.`);
    await expect(dialog).toContainText('הנתונים שיצר/ה נשמרים.');
    await closeWithoutConfirm(page, dialog);
    await expect(row).toContainText('פעיל');
    await expect(row).not.toContainText('חסום');

    // «הסרה מהעסק» — окно (FL-07: записи остаются связаны с участником).
    menu = await openMemberMenu(page, name);
    await menu.getByRole('menuitem', { name: 'הסרה מהעסק' }).click();
    await expect(dialog).toContainText(`להסיר את ${name} מהעסק?`);
    await expect(dialog).toContainText(`הגישה של ${name} לנתוני העסק תסתיים מיד.`);
    await expect(dialog).toContainText('הנתונים שיצר/ה נשמרים ומשויכים אליו/אליה.');
    await closeWithoutConfirm(page, dialog);
    await expect(rows.filter({ hasText: name })).toHaveCount(1);

    // «ביטול החסימה» — только если в списке уже есть заблокированный участник (сами не блокируем).
    const blockedRow = rows.filter({ has: page.getByRole('button', { name: MEMBER_MENU }) }).filter({ hasText: 'חסום' });
    if ((await blockedRow.count()) > 0) {
      const blockedName = await memberName(blockedRow.first());
      menu = await openMemberMenu(page, blockedName);
      await expect(menu.getByRole('menuitem', { name: 'ביטול החסימה' })).toBeVisible();
      await expect(menu.getByRole('menuitem', { name: 'חסימת משתמש' })).toHaveCount(0);
      await menu.getByRole('menuitem', { name: 'ביטול החסימה' }).click();
      await expect(dialog).toContainText(`לבטל את החסימה של ${blockedName}?`);
      await expect(dialog).toContainText('להתחבר שוב עם ההרשאה הקיימת.');
      await closeWithoutConfirm(page, dialog);
      await expect(blockedRow.first()).toContainText('חסום');
    } else {
      test.info().annotations.push({ type: 'note', description: 'в testim нет заблокированного участника — окно «ביטול החסימה» не проверено (UA-009 вручную)' });
    }

    expect(blocked, 'окна без подтверждения не должны ничего записывать на сервер').toEqual([]);
  });
});
